import React, { useContext } from 'react';
import { TripContext } from '../context/TripContext';

const TripSummary = () => {
  const { families, expenses } = useContext(TripContext);

  // Count total people (all members across all families including heads)
  const totalPeople = families.reduce((sum, fam) => sum + fam.members.length + 1, 0);

  // Total amount spent
  const totalExpense = expenses.reduce((sum, exp) => sum + exp.amount, 0);

  // Cost per person
  const perPersonCost = totalPeople ? totalExpense / totalPeople : 0;

  // Map each family head to what they paid and what they owe
  const summary = families.map(family => {
    const memberCount = family.members.length + 1; // +1 for head
    const share = memberCount * perPersonCost;

    const paid = expenses
      .filter(exp => exp.paidBy === family.head)
      .reduce((sum, exp) => sum + exp.amount, 0);

    return {
      family: family.head,
      paid,
      share,
      balance: paid - share,
    };
  });

  return (
    <div style={{ marginTop: '30px', border: '1px solid #ccc', padding: '15px', borderRadius: '8px' }}>
      <h3>Trip Summary</h3>
      <p><strong>Total Expense:</strong> ₹{totalExpense}</p>
      <p><strong>Per Person Share:</strong> ₹{perPersonCost.toFixed(2)}</p>
      <ul>
        {summary.map((item, index) => (
          <li key={index}>
            <strong>{item.family}</strong> paid ₹{item.paid.toFixed(2)}, should pay ₹{item.share.toFixed(2)} ⇒
            {item.balance > 0
              ? ` gets ₹${item.balance.toFixed(2)}`
              : ` owes ₹${(-item.balance).toFixed(2)}`}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default TripSummary;
